import { sha256 } from "node:crypto";

/**
 * Local identity backup phrase helpers (issue #1256).
 *
 * This phrase is generated by the app for backing up the exported identity
 * record. It is deliberately NOT the Freighter wallet seed phrase: the app
 * never asks for or stores wallet secrets. Only a one-way fingerprint is
 * persisted after the backup flow is confirmed.
 */

const WORDLIST = [
  "anchor", "arctic", "arbor", "atlas", "aurora", "badge", "bamboo", "beacon",
  "birch", "blaze", "bloom", "brave", "bridge", "brook", "cactus", "canyon",
  "cedar", "cipher", "cliff", "cloud", "coral", "cosmos", "crater", "crystal",
  "dawn", "delta", "desert", "dolphin", "drift", "ember", "fable", "falcon",
  "feather", "final", "flame", "forest", "fossil", "galaxy", "garden", "glacier",
  "globe", "harbor", "hazel", "heron", "horizon", "island", "ivory", "jungle",
  "kanji", "ladder", "lagoon", "lantern", "lava", "legend", "liberty", "lunar",
  "maple", "marble", "meadow", "meteor", "mosaic", "mountain", "nebula", "needle",
  "oak", "ocean", "olive", "onyx", "orbit", "orchid", "otter", "palace",
  "panda", "paper", "pebble", "pepper", "pilot", "pioneer", "planet", "plume",
  "prairie", "prism", "quartz", "raven", "reef", "ribbon", "ridge", "river",
  "robust", "rocket", "saddle", "saffron", "sail", "sand", "satellite", "shell",
  "signal", "silver", "solar", "sparrow", "summit", "sunset", "temple", "thicket",
  "thunder", "timber", "tulip", "valley", "velvet", "violet", "willow", "winter",
  "zephyr", "zigzag", "zircon", "zenith", "anchorite", "asteroid", "basalt", "bison",
  "cobalt", "comet", "dahlia", "dune", "eagle", "emberly", "fjord", "granite",
  "hollow", "indigo", "juniper", "kelp", "lilac", "mango", "nimbus", "opal",
] as const;

export const PHRASE_WORD_COUNT = 12;
export const CONFIRMATION_WORD_COUNT = 3;

/** Uniform random index below `max`, with rejection sampling to avoid modulo bias. */
function randomIndex(max: number, random: () => number): number {
  const limit = Math.floor(0x100000000 / max) * max;
  let value = 0;
  do {
    value = random() * 0x100000000;
  } while (value >= limit);
  return Math.floor(value) % max;
}

function defaultRandom(): number {
  const bytes = new Uint32Array(1);
  globalThis.crypto.getRandomValues(bytes);
  return bytes[0] / 0x100000000;
}

export function generateRecoveryPhrase(
  random: () => number = defaultRandom,
): string {
  return Array.from(
    { length: PHRASE_WORD_COUNT },
    () => WORDLIST[randomIndex(WORDLIST.length, random)].trim(),
  ).join(" ");
}

export interface ConfirmationWord {
  /** 1-based position in the phrase. */
  position: number;
  word: string;
}

/** Picks distinct word positions the user must confirm before continuing. */
export function pickConfirmationWords(
  phrase: string,
  count = CONFIRMATION_WORD_COUNT,
  random: () => number = defaultRandom,
): ConfirmationWord[] {
  const words = normalizePhrase(phrase).split(" ").filter(Boolean);
  if (words.length === 0) throw new Error("A recovery phrase is required");
  const total = Math.min(count, words.length);
  const positions = new Set<number>();
  // A broken or mocked RNG that always returns the same value must not hang
  // the flow, so bound the attempts and fill sequentially as a fallback.
  let attempts = 0;
  const maxAttempts = words.length * 20;
  while (positions.size < total && attempts < maxAttempts) {
    positions.add(1 + randomIndex(words.length, random));
    attempts += 1;
  }
  for (let position = 1; position <= words.length && positions.size < total; position += 1) {
    positions.add(position);
  }
  return [...positions]
    .sort((a, b) => a - b)
    .map((position) => ({ position, word: words[position - 1] }));
}

export function normalizePhrase(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, " ");
}

export function isConfirmationCorrect(
  phrase: string,
  answers: Record<number, string>,
  questions: ConfirmationWord[],
): boolean {
  const words = normalizePhrase(phrase).split(" ");
  return questions.every(
    ({ position, word }) => normalizePhrase(answers[position] ?? "") === word,
  ) && words.length > 0;
}

/** One-way fingerprint so the app can remember completion without keeping the phrase. */
export async function fingerprintPhrase(phrase: string): Promise<string> {
  const data = new TextEncoder().encode(normalizePhrase(phrase));
  // Web Crypto in browsers; the repo's Vite alias supplies `sha256` for
  // environments without subtle (for example jsdom in the test suite).
  const digest = globalThis.crypto?.subtle
    ? new Uint8Array(await globalThis.crypto.subtle.digest("SHA-256", data))
    : sha256(data);
  return [...digest]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}
